import { components } from './missions.js';
import { readingRange } from './diagnostics.js';
import { ADC_SIGNALS, ADC_SCALE } from './signals.js';
import { clamp } from './world-math.js';
// Real board over Web Serial. A small program on the board (generated by boardProgram for the
// student's own circuit) prints sensor readings as lines like
//   IOTQ light=2310 motion=1
// and, optionally, sets real outputs from lines the game sends back:
//   OUT 26=1 25=128
// Readings replace the simulated sensors, so a real hand over a real sensor drives the simulation.

export const BAUD = 115200;
const PREFIX = 'IOTQ',
  MAX_LINE = 500;
const known = new Set(components.filter((c) => !c.output && c.signal).map((c) => c.signal));

// One protocol line to { signal: reading }, or null if it is not a readings line.
export function parseReadingLine(line) {
  line = String(line).trim();
  // An overlong line is noise or a corrupted read, never a reading.
  if (line.length > MAX_LINE) return null;
  const parts = line.split(/\s+/);
  if (parts[0] !== PREFIX) return null;
  const readings = {};
  for (const part of parts.slice(1)) {
    const m = part.match(/^(\w+)=(-?\d+(?:\.\d+)?)$/);
    if (m && known.has(m[1]) && Number.isFinite(Number(m[2]))) readings[m[1]] = Number(m[2]);
  }
  return Object.keys(readings).length ? readings : null;
}

// Board readings to the simulation's units: ADC sensors are stored as 0–100, others as read.
export function readingsToEnv(readings) {
  const env = {};
  for (const [signal, value] of Object.entries(readings)) {
    const device = components.find((c) => c.signal === signal),
      [lo, hi] = readingRange(device) || [-Infinity, Infinity],
      reading = clamp(value, lo, hi);
    env[signal] = ADC_SIGNALS.includes(signal) ? reading / ADC_SCALE : reading;
  }
  return env;
}

export function outputLine(outputs, devices) {
  const pins = devices
    .filter((d) => d.output)
    .map((d) => d.pin + '=' + Math.round(outputs[d.pin] || 0));
  return pins.length ? 'OUT ' + pins.join(' ') + '\n' : '';
}

const SIMPLE = (d) => ADC_SIGNALS.includes(d.signal) || !d.analog;
// A board program for the installed devices: Arduino C++ for ESP32, MicroPython for Pico.
// Sensors that need a library (temperature, humidity, distance…) are left as clear TODOs.
export function boardProgram(devices, board) {
  const sensors = devices.filter((d) => !d.output && d.signal),
    outputs = devices.filter((d) => d.output),
    todo = sensors.filter((d) => !SIMPLE(d));
  if (board === 'ESP32')
    return (
      '// IoT Quest board link for ESP32. Upload with the Arduino IDE, then press\n' +
      '// "Connect a real board" in the game (Live circuit). Readings go to the game;\n' +
      "// the game's outputs come back.\n\n" +
      'void setup() {\n  Serial.begin(' +
      BAUD +
      ');\n' +
      sensors
        .filter(SIMPLE)
        .filter((d) => !d.analog)
        .map((d) => '  pinMode(' + d.pin + ', INPUT);\n')
        .join('') +
      outputs.map((d) => '  pinMode(' + d.pin + ', OUTPUT);\n').join('') +
      '}\n\nvoid loop() {\n  Serial.print("' +
      PREFIX +
      '");\n' +
      sensors
        .filter(SIMPLE)
        .map(
          (d) =>
            '  Serial.print(" ' +
            d.signal +
            '=");\n  Serial.print(' +
            (d.analog ? 'analogRead' : 'digitalRead') +
            '(' +
            d.pin +
            '));\n',
        )
        .join('') +
      todo
        .map(
          (d) =>
            '  // TODO: read the ' +
            d.name +
            ' with its library, then:\n  // Serial.print(" ' +
            d.signal +
            '="); Serial.print(value);\n',
        )
        .join('') +
      '  Serial.println();\n' +
      (outputs.length
        ? `  // Outputs from the game: "OUT pin=value pin=value"
  while (Serial.available()) {
    String line = Serial.readStringUntil('\\n');
    if (!line.startsWith("OUT ")) continue;
    int at = 4;
    while (at < (int)line.length()) {
      int eq = line.indexOf('=', at), end = line.indexOf(' ', at);
      if (end < 0) end = line.length();
      if (eq < 0 || eq > end) break;
      int pin = line.substring(at, eq).toInt(), value = line.substring(eq + 1, end).toInt();
      // Only this circuit's output pins can be set.
      if (${outputs.map((d) => 'pin == ' + d.pin).join(' || ')}) {
        if (value == 0 || value == 1) digitalWrite(pin, value);
        else analogWrite(pin, value);
      }
      at = end + 1;
    }
  }
`
        : '') +
      '  delay(200);\n}\n'
    );
  return (
    '# IoT Quest board link for Raspberry Pi Pico. Save as main.py with Thonny, then press\n' +
    '# "Connect a real board" in the game (Live circuit). Readings go to the game;\n' +
    "# the game's outputs come back.\n" +
    'from machine import Pin, ADC, PWM\nimport sys, select, time\n\n' +
    sensors
      .filter(SIMPLE)
      .map((d) =>
        d.analog
          ? d.signal + '_sensor = ADC(Pin(' + d.pin + '))\n'
          : d.signal + '_sensor = Pin(' + d.pin + ', Pin.IN)\n',
      )
      .join('') +
    outputs.map((d) => 'out_' + d.pin + ' = Pin(' + d.pin + ', Pin.OUT)\n').join('') +
    'poll = select.poll()\npoll.register(sys.stdin, select.POLLIN)\n\nwhile True:\n    parts = ["' +
    PREFIX +
    '"]\n' +
    sensors
      .filter(SIMPLE)
      .map(
        (d) =>
          '    parts.append("' +
          d.signal +
          '=" + str(' +
          (d.analog ? d.signal + '_sensor.read_u16() >> 4' : d.signal + '_sensor.value()') +
          '))\n',
      )
      .join('') +
    todo
      .map(
        (d) =>
          '    # TODO: read the ' +
          d.name +
          ' with its library and append "' +
          d.signal +
          '=<value>"\n',
      )
      .join('') +
    '    print(" ".join(parts))\n' +
    (outputs.length
      ? '    while poll.poll(0):\n        line = sys.stdin.readline().strip()\n        if line.startswith("OUT "):\n            for item in line[4:].split():\n                try:\n                    pin, value = item.split("=")\n                    value = int(value)\n                except ValueError:\n                    continue\n' +
        outputs
          .map(
            (d) =>
              '                if pin == "' +
              d.pin +
              '":\n                    if value in (0, 1):\n                        out_' +
              d.pin +
              '.value(value)\n                    else:\n                        PWM(Pin(' +
              d.pin +
              ')).duty_u16(value * 257)\n',
          )
          .join('')
      : '') +
    '    time.sleep_ms(200)\n'
  );
}

// The serial connection. `port` is a Web Serial port (or anything with the same shape, for tests).
export class BoardLink {
  constructor({ onReadings, onStatus } = {}) {
    this.onReadings = onReadings || (() => {});
    this.onStatus = onStatus || (() => {});
    this.port = null;
    this.lastLine = '';
    this.lastSent = '';
  }
  static supported() {
    return typeof navigator !== 'undefined' && 'serial' in navigator;
  }
  async connect(port) {
    port ??= await navigator.serial.requestPort();
    await port.open({ baudRate: BAUD });
    this.port = port;
    this.onStatus('connected');
    this.reading = this.readLoop();
    return true;
  }
  async readLoop() {
    const decoder = new TextDecoder();
    let buffer = '';
    try {
      this.reader = this.port.readable.getReader();
      for (;;) {
        const { value, done } = await this.reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        // A line that never ends is not a reading: drop it rather than grow forever.
        if (buffer.length > MAX_LINE * 4) buffer = buffer.slice(-MAX_LINE);
        let end;
        while ((end = buffer.indexOf('\n')) >= 0) {
          const line = buffer.slice(0, end).replace(/\r$/, '');
          buffer = buffer.slice(end + 1);
          const readings = parseReadingLine(line);
          if (readings) {
            this.lastLine = line;
            this.onReadings(readings);
          }
        }
      }
    } catch {
      // The board was unplugged or the port closed.
    } finally {
      this.reader?.releaseLock();
      this.reader = null;
      if (this.port) this.onStatus('disconnected');
    }
  }
  async send(text) {
    if (!this.port?.writable || !text || text === this.lastSent) return;
    this.lastSent = text;
    const writer = this.port.writable.getWriter();
    try {
      await writer.write(new TextEncoder().encode(text));
    } finally {
      writer.releaseLock();
    }
  }
  async disconnect() {
    const port = this.port;
    this.port = null;
    await this.reader?.cancel().catch(() => {});
    await this.reading;
    await port?.close().catch(() => {});
    this.onStatus('disconnected');
  }
}
